// Match each Drive file to a store, work out its date, and drop the ones
// already recorded. Same rules as scripts/ingest-drive.mjs.

// Flip to true for a one-off replay of a date that is already recorded.
// Only a store's NEWEST date can be replayed: ingest_store_day() rewinds that
// run and redoes it. An older date is refused by the database rather than
// merged, because the current-state layer holds the newest values and diffing
// an older file against them would write nonsense.
const FORCE = false;

const files = $('List Drive files').all().flatMap(i => i.json.files || []);
const meta  = $input.first().json.meta;
const stores = meta.stores || [];
const done   = new Set((meta.done || []).map(String));

/** Date from the filename if it carries one, else the file's own Drive timestamp. */
const dateFor = (name, modifiedTime) => {
  let m = name.match(/(\d{4})[-_](\d{2})[-_](\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = name.match(/(\d{2})[-_](\d{2})[-_](\d{2,4})/);
  if (m) return `${m[3].length === 2 ? '20' + m[3] : m[3]}-${m[2]}-${m[1]}`;
  return new Date(modifiedTime).toISOString().slice(0, 10);
};

/** Longest matching csv_prefix wins, so similar domains cannot collide. */
const storeFor = name => {
  const n = name.toLowerCase();
  return stores
    .filter(s => s.csv_prefix && n.startsWith(String(s.csv_prefix).toLowerCase()))
    .sort((a, b) => String(b.csv_prefix).length - String(a.csv_prefix).length)[0] || null;
};

const jobs = [], skipped = [], unmatched = [];

for (const f of files) {
  if (!/\.csv$/i.test(f.name)) continue;
  const store = storeFor(f.name);
  // Never guess. A file matching no store is reported and left alone.
  if (!store) { unmatched.push(f.name); continue; }
  const run_date = dateFor(f.name, f.modifiedTime);
  if (!FORCE && done.has(`${store.id}|${run_date}`)) { skipped.push(`${f.name} → ${run_date}`); continue; }
  jobs.push({
    file_id: f.id, file_name: f.name,
    store_id: store.id, store_name: store.name, run_date,
    mb: ((Number(f.size) || 0) / 1e6).toFixed(1),
  });
}

console.log(`${files.length} file(s) · ${jobs.length} to ingest · ${skipped.length} already done · ${unmatched.length} unmatched`);
if (unmatched.length) console.log('unmatched (no store csv_prefix matches):', unmatched.join(', '));
if (skipped.length)   console.log('already ingested:', skipped.join(', '));

return jobs.map(j => ({ json: { ...j, _skipped: skipped, _unmatched: unmatched } }));

// Parse the CSV and build the one statement that does the whole ingest.
//
// Everything above the divider is lib/csv-to-payload.mjs verbatim — the Code
// node cannot require csv-parse, and a test runs both over the same bytes and
// checks they agree. The diff itself is NOT here: it lives in
// ingest_store_day(), so n8n and scripts/ingest.mjs cannot drift apart.

/**
 * RFC 4180. Quoted fields may hold commas, newlines and doubled quotes, and
 * Shopify's Body (HTML) column holds all three.
 *
 * A quote only opens a quoted field at the start of one. Mid-field quotes are
 * literal — csv-parse behaves this way under relax_quotes, and product
 * descriptions contain plenty of stray inch marks.
 *
 * Written around indexOf/slice rather than a character loop. The character
 * version was clear but did ~8 million iterations on a 7.9 MB export, and the
 * n8n Code node runs inside a sandboxed VM where that took minutes. indexOf and
 * slice are native, so the sandbox barely slows them down.
 */
function parseCsv (text) {
  const src = String(text).replace(/^﻿/, '')
  const n = src.length
  const rows = []
  let row = []
  let i = 0

  while (i < n) {
    let field

    if (src[i] === '"') {
      // Quoted: hop from quote to quote. A doubled quote is an escaped one and
      // the field continues; a lone quote ends it.
      let j = i + 1
      let buf = null                      // stays null while there is no escape
      let start = j
      for (;;) {
        const k = src.indexOf('"', j)
        if (k < 0) { field = (buf ?? '') + src.slice(start); i = n; break }
        if (src[k + 1] === '"') {
          buf = (buf ?? '') + src.slice(start, k + 1)
          j = k + 2
          start = j
          continue
        }
        field = buf === null ? src.slice(start, k) : buf + src.slice(start, k)
        i = k + 1
        break
      }
    } else {
      // Unquoted: run to whichever delimiter comes first.
      let c = src.indexOf(',', i); if (c < 0) c = n
      let l = src.indexOf('\n', i); if (l < 0) l = n
      const end = c < l ? c : l
      field = src.slice(i, end)
      if (field.charCodeAt(field.length - 1) === 13) field = field.slice(0, -1)  // trailing \r
      i = end
    }

    row.push(field)

    if (i >= n) break
    if (src[i] === ',') { i++; continue }
    if (src[i] === '\r') i++
    if (src[i] === '\n') { rows.push(row); row = []; i++; continue }
    // A stray character after a closing quote: skip to the next delimiter
    // rather than losing the rest of the file to it.
    let c = src.indexOf(',', i); if (c < 0) c = n
    let l = src.indexOf('\n', i); if (l < 0) l = n
    if (c < l) { i = c + 1 } else { rows.push(row); row = []; i = l + 1 }
  }

  if (row.length) rows.push(row)
  return rows
}

const s = v => (v ?? '').toString().trim()

const num = v => {
  const n = parseFloat(String(v ?? '').replace(/,/g, ''))
  return Number.isFinite(n) ? n : null
}

/** Blank = sellable, explicit 0 = sold out, a real number = that many left. */
const available = raw => {
  const t = s(raw)
  if (t === '') return true
  const n = Number(t)
  return Number.isFinite(n) ? n > 0 : true
}

/**
 * The raw Inventory quantity, or null when the store gave nothing usable. A 0
 * is a state marker, not a count — it says the variant sold out, never how many
 * there had been, so it is not reported as a quantity.
 */
const qty = raw => {
  const t = s(raw)
  if (t === '') return null
  const n = Number(t)
  return Number.isFinite(n) && n > 0 ? Math.trunc(n) : null
}

function csvToPayload (text) {
  const rows = parseCsv(text)
  if (!rows.length) return { products: [], variants: [], rows: 0 }

  // Column positions are resolved once. Looking each cell up by name meant a
  // string lookup and a closure call ~20 times per row across tens of thousands
  // of rows — cheap natively, and not cheap inside the sandbox the n8n Code
  // node runs in.
  const idx = {}
  rows[0].forEach((h, n) => { const k = s(h); if (!(k in idx)) idx[k] = n })
  const at = name => (name in idx ? idx[name] : -1)

  const iHandle  = at('Handle')
  const iTitle   = at('Title')
  const iVendor  = at('Vendor')
  const iType    = at('Type')
  const iTags    = at('Tags')
  const iPub     = at('Published')
  const iStatus  = at('Status')
  const iImage   = at('Image Src')
  const iSku     = at('Variant SKU')
  const iPrice   = at('Variant Price')
  const iCompare = at('Variant Compare At Price')
  const iVImage  = at('Variant Image')
  const iInv     = at('Inventory quantity')
  const iO1n = at('Option1 Name'), iO1v = at('Option1 Value')
  const iO2n = at('Option2 Name'), iO2v = at('Option2 Value')
  const iO3n = at('Option3 Name'), iO3v = at('Option3 Value')

  const g = (row, i) => (i < 0 ? '' : s(row[i]))

  const products = new Map()   // handle          -> product
  const variants = new Map()   // handle\0key     -> variant
  let dataRows = 0

  for (let r = 1; r < rows.length; r++) {
    const row = rows[r]
    // csv-parse's skip_empty_lines drops a blank line, which this parser
    // returns as a single empty field. A row of genuinely empty columns is a
    // real row and stays counted, exactly as csv-parse counts it.
    if (row.length === 1 && row[0] === '') continue
    dataRows++

    const handle = g(row, iHandle)
    if (!handle) continue

    // The parent row carries the product-level fields; image-only rows that
    // follow it may still be the first to name an image.
    const title = g(row, iTitle)
    if (title) {
      const tags = g(row, iTags)
      products.set(handle, {
        handle,
        title,
        vendor:       g(row, iVendor) || null,
        product_type: g(row, iType) || null,
        tags:         tags ? tags.split(',').map(t => t.trim()).filter(Boolean) : [],
        published:    g(row, iPub) || null,
        status:       g(row, iStatus) || null,
        image_src:    g(row, iImage) || null,
      })
    } else {
      const p = products.get(handle)
      if (p && !p.image_src) {
        const img = g(row, iImage)
        if (img) p.image_src = img
      }
    }

    // a variant row has a SKU or a price
    const sku   = g(row, iSku)
    const price = g(row, iPrice)
    if (!sku && !price) continue

    const o1 = g(row, iO1v), o2 = g(row, iO2v), o3 = g(row, iO3v)
    const variant_key = [sku, o1, o2, o3].join('|')   // SKUs repeat; options disambiguate
    const key = handle + '�' + variant_key
    if (variants.has(key)) continue

    const inv = iInv < 0 ? '' : row[iInv]
    variants.set(key, {
      handle, variant_key,
      sku: sku || null,
      option1_name: g(row, iO1n) || null, option1_value: o1 || null,
      option2_name: g(row, iO2n) || null, option2_value: o2 || null,
      option3_name: g(row, iO3n) || null, option3_value: o3 || null,
      variant_image: g(row, iVImage) || null,
      price: num(price),
      compare_at: num(iCompare < 0 ? '' : row[iCompare]),
      // Inventory quantity does carry the stock signal: blank means sellable,
      // an explicit 0 means sold out. Checked against the store's live
      // /products.json feed — 99.2% agreement over 3,406 variants.
      available: available(inv),
      qty: qty(inv),
    })
  }

  return {
    products: [...products.values()],
    variants: [...variants.values()],
    rows: dataRows,
  }
}

// ── build the statement ───────────────────────────────────────────
// batchSize is 1, so the loop node is holding exactly this file's job.
const job = $('Loop over files').first().json;
const csv = $input.first().json.csv ?? $input.first().json.data ?? '';

if (!/^\d{4}-\d{2}-\d{2}$/.test(String(job.run_date))) {
  throw new Error(`refusing to build SQL for a run_date that is not YYYY-MM-DD: ${job.run_date}`);
}
const storeId = Number(job.store_id);
if (!Number.isInteger(storeId)) throw new Error(`store_id is not a number: ${job.store_id}`);

const payload = csvToPayload(csv);
if (!payload.variants.length) {
  throw new Error(`${job.file_name} parsed to 0 variants — refusing to send an empty payload`);
}

// Dollar quoting carries any JSON safely; the tag cannot occur inside JSON,
// because $ing$ is not a sequence JSON.stringify can emit.
const json = JSON.stringify(payload);
const quoted = str => "'" + String(str).replace(/'/g, "''") + "'";

const sql =
  `SELECT ingest_store_day(${storeId}, ${quoted(job.run_date)}, ${quoted(job.file_name)}, ` +
  `${payload.rows}, $ing$${json}$ing$::jsonb) AS result`;

console.log(`${job.store_name} · ${job.run_date} · ${job.file_name} — ` +
            `${payload.rows} rows → ${payload.products.length} products, ${payload.variants.length} variants`);

return [{ json: { ...job, products: payload.products.length, variants: payload.variants.length, sql } }];

// One line per store, plus whatever was skipped or unmatched.

const results = $('Run ingest_store_day').all().map(i => {
  const r = i.json.result;
  return typeof r === 'string' ? JSON.parse(r) : r;
}).filter(Boolean);

const jobs = $('Decide what to ingest').all().map(i => i.json);
const first = jobs[0] || {};

const lines = results.map(r => {
  const job = jobs.find(j => Number(j.store_id) === Number(r.store_id) && j.run_date === r.run_date);
  const name = job ? job.store_name : `store ${r.store_id}`;
  const counts = Object.entries(r.counts || {}).map(([k, v]) => `${k} ${v}`).join(', ');
  return `${r.status === 'success' ? '✓' : '!'} ${name} · ${r.run_date} — ${r.changes} changes` +
         (counts ? ` (${counts})` : '') +
         (r.removals_skipped ? '  ⚠ feed collapsed, removals skipped' : '');
});

const partial = results.filter(r => r.status !== 'success').length;

console.log(lines.join('\n') || 'nothing was ingested');

return [{
  json: {
    ingested: results.length,
    partial,
    total_changes: results.reduce((n, r) => n + (r.changes || 0), 0),
    already_done: first._skipped || [],
    unmatched: first._unmatched || [],
    stores: lines,
    results,
  },
}];
